#pragma once
#include "../behavioral/observer.hpp"
namespace algs {
template<class T> class TypedEventEmitter { using Listener = std::shared_ptr<Observer<T>>; struct State { std::map<std::string, std::vector<Listener>> listeners; }; std::shared_ptr<State> state = std::make_shared<State>(); public: std::function<void()> on(std::string event, Listener listener) { auto& list = state->listeners[event]; if (std::find(list.begin(), list.end(), listener) == list.end()) list.push_back(listener); std::weak_ptr<State> weak = state; return [weak, event, listener] { if (auto state = weak.lock()) std::erase(state->listeners[event], listener); }; } std::function<void()> once(std::string event, Listener listener) { std::weak_ptr<State> weak = state; auto wrapper = std::make_shared<Observer<T>>([](const T&) {}); std::weak_ptr<Observer<T>> weakWrapper = wrapper; wrapper->callback = [weak, event, listener, weakWrapper](const T& value) { if (auto state = weak.lock()) if (auto wrapper = weakWrapper.lock()) std::erase(state->listeners[event], wrapper); listener->callback(value); }; return on(std::move(event), wrapper); } void off(const std::string& event, const Listener& listener) { auto it = state->listeners.find(event); if (it != state->listeners.end()) std::erase(it->second, listener); } std::size_t emit(const std::string& event, const T& value) { auto it = state->listeners.find(event); if (it == state->listeners.end()) return 0; auto snapshot = it->second; for (auto& listener : snapshot) listener->callback(value); return listenerCount(event); } std::size_t listenerCount(const std::string& event) const { auto it = state->listeners.find(event); return it == state->listeners.end() ? 0 : it->second.size(); } };
}
